css:
/* Frutiger Aero: glossy glass, soft drop shadows on text, bubbles of light. */
.title-h, .info h3, .item b, #who, .wk-info h1 { text-shadow: 0 1px 0 rgba(255,255,255,.55), 0 2px 8px rgba(0, 60, 120, .28); }
.blade, .dlg, .fw, #np, #run, #dock { backdrop-filter: blur(14px) saturate(1.35); }
.blade::before { background: linear-gradient(180deg, rgba(255,255,255,.55), rgba(255,255,255,.08) 48%, transparent 52%) !important; }
.item.sel { background: linear-gradient(180deg, color-mix(in srgb, var(--accent-hi) 92%, #fff), var(--accent) 55%, color-mix(in srgb, var(--accent) 80%, #000)) !important; }
button.primary, .primary { background: linear-gradient(180deg, #ffffff 0%, var(--accent-hi) 45%, var(--accent) 55%, color-mix(in srgb, var(--accent) 70%, #003) 100%) !important; color: #fff !important; text-shadow: 0 1px 1px rgba(0,0,0,.35); }
body::before { content: ""; position: fixed; inset: -20% -10% auto -10%; height: 70%; pointer-events: none; z-index: 0;
  background: radial-gradient(60% 50% at 30% 30%, rgba(255,255,255,.45), transparent 70%), radial-gradient(40% 40% at 80% 20%, rgba(255,255,255,.25), transparent 70%); }
